import { Component, EventEmitter, Input, Output, OnInit, OnDestroy, ViewChild, ElementRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { NgHcaptchaModule, CAPTCHA_CONFIG } from 'ng-hcaptcha';
import { Subscription } from 'rxjs';
import { CaptchaService, CaptchaState } from '../../services/captcha.service';
import { MensagemService } from '../../services/mensagem.service';

@Component({
  selector: 'app-captcha',
  templateUrl: './captcha.component.html',
  styleUrls: ['./captcha.component.scss'],
  standalone: true,
  providers: [
    {
      provide: CAPTCHA_CONFIG,
      useFactory: (captchaService: CaptchaService) => ({
        siteKey: captchaService.siteKey,
        languageCode: 'pt-BR'
      }),
      deps: [CaptchaService]
    }
  ],
  imports: [
    CommonModule,
    NgHcaptchaModule
  ]
})
export class CaptchaComponent implements OnInit, OnDestroy {
  @Input() invisible: boolean = true;
  @Output() verified = new EventEmitter<string>();
  @Output() expired = new EventEmitter<void>();
  @Output() error = new EventEmitter<any>();

  @ViewChild('hcaptchaButton', { static: false }) hcaptchaButton!: ElementRef;

  captchaState: CaptchaState | null = null;
  private subscription = new Subscription();

  constructor(
    private captchaService: CaptchaService,
    private mensagemService: MensagemService
  ) {}

  ngOnInit(): void {
    this.subscription.add(
      this.captchaService.captchaState$.subscribe(state => {
        this.captchaState = state;
        // acionamento automático do captcha quando o processamento é necessário e ainda não verificado
        if (state.isProcessing && !state.isVerified && this.hcaptchaButton?.nativeElement) {
          // delay para esperar o componente estar pronto
          setTimeout(() => {
            if (this.hcaptchaButton?.nativeElement) {
              this.hcaptchaButton.nativeElement.click();
            }
          }, 100);
        }
      })
    );
  }

  ngOnDestroy(): void {
    this.subscription.unsubscribe();
  }

  get siteKey(): string {
    return this.captchaService.siteKey;
  }

  /**
   * Acionamento manual do captcha
   */
  triggerCaptcha(): void {
    if (this.hcaptchaButton?.nativeElement) {
      this.captchaService.setProcessing(true);
      this.hcaptchaButton.nativeElement.click();
    }
  }

  /**
   * Trata a verificação bem-sucedida do captcha
   */
  handleVerify(event: any): void {
    const token = typeof event === 'string' ? event : event?.token || event;
    this.captchaService.setVerified(token);
    this.mensagemService.mostrar('Captcha', 'Sucesso', 'Verificação de segurança concluída com sucesso!');
    this.verified.emit(token);
  }

  /**
   * Trata a expiração do captcha
   */
  handleExpired(event: any): void {
    this.captchaService.setExpired();
    this.mensagemService.mostrar('Captcha', 'Aviso', 'Verificação de segurança expirou. Tente novamente.');
    this.expired.emit();
  }

  /**
   * Trata o erro do captcha
   */
  handleError(error: any): void {
    this.captchaService.setError('Erro na verificação de segurança');
    this.mensagemService.mostrar('Captcha', 'Erro', 'Erro na verificação de segurança. Tente novamente.');
    this.error.emit(error);
  }
}
