import { Component, ElementRef, Input, OnInit, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { DispositivoService } from '../../../services/dispositivo.service';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { GovBrModalModule } from '@serpro/ngx-dsgovbr';
import { BsModalService, ModalOptions } from 'ngx-bootstrap/modal';
import { ModalDetalhesComponent } from '../modal-detalhes/modal-detalhes.component';
import { SimuladorCalculoRelatorioComponent } from '../simulador-calculo-relatorio/simulador-calculo-relatorio.component';
import { DadosCalculadoraService } from '../../../services/dados-calculadora.service';

import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { ModalGeradorValidadorXmlComponent } from '../modal-gerador-validador-xml/modal-gerador-validador-xml.component';

@Component({
  selector: 'simulador-calculo-resultado',
  templateUrl: './simulador-calculo-resultado.component.html',
  styleUrl: './simulador-calculo-resultado.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    TooltipModule,
    GovBrModalModule,
    SimuladorCalculoRelatorioComponent
  ]
})
export class SimuladorCalculoResultadoComponent implements OnInit {

  @Input() dados!: any;
  @Input() tipoAliquota!: string;
  @Input() unidadeMedida!: string;
  //@Input() total!: number;
  @Input() mostrarNcm!: boolean;

  @ViewChild('relatorioPdf', { static: false }) relatorioPdf!: ElementRef;

  private readonly subscriptions: Subscription = new Subscription();

  dispositivo: string = '';

  output!: any;
  total!: any;
  isGerandoPdf: boolean = false;

  constructor(
    private readonly dispositivoService: DispositivoService,
    private readonly bsModalService: BsModalService,
    public dadosCalculadoraService: DadosCalculadoraService
  ) { }

  ngOnInit(): void {
    this.output = this.dadosCalculadoraService.output.objetos[0].tribCalc;
    this.total = this.dadosCalculadoraService.output.total.tribCalc;
    this.setSubscriptions();
  }
  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  toNumber(x: string | number): number {
    let num: number = Number(x);
    if (isNaN(num)) {
      console.error("Erro na conversão para número");
      return 0;
    }
    return num;
  }


  baixarPdf() {
    if (this.isGerandoPdf) return; // Evita múltiplos cliques
    
    this.isGerandoPdf = true;
    const element = this.relatorioPdf.nativeElement;
    
    // Configurações otimizadas para melhor performance
    const options = {
      scale: 1.5, // Reduzido de 2 para melhorar performance
      useCORS: true,
      allowTaint: false,
      backgroundColor: '#ffffff',
      width: element.scrollWidth,
      height: element.scrollHeight,
      scrollX: 0,
      scrollY: 0
    };

    html2canvas(element, options).then((canvas) => {
      const imgData = canvas.toDataURL('image/jpeg', 0.8); // JPEG com qualidade 80% para arquivo menor
      
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4',
        compress: true // Compressão ativada
      });

      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();
      
      // Calculando dimensões para ajustar perfeitamente numa página A4
      const imgProps = pdf.getImageProperties(imgData);
      const imgWidth = pageWidth;
      const imgHeight = (imgProps.height * pageWidth) / imgProps.width;
      
      // Se a altura exceder a página, ajusta proporcionalmente
      const finalWidth = imgHeight > pageHeight ? (pageWidth * pageHeight) / imgHeight : imgWidth;
      const finalHeight = imgHeight > pageHeight ? pageHeight : imgHeight;
      
      // Centraliza na página
      const x = (pageWidth - finalWidth) / 2;
      const y = (pageHeight - finalHeight) / 2;
      
      pdf.addImage(imgData, 'JPEG', x, y, finalWidth, finalHeight);
      pdf.save('relatorio-tributario.pdf');
    }).catch((error) => {
      console.error('Erro ao gerar PDF:', error);
    }).finally(() => {
      this.isGerandoPdf = false; // Sempre desativa o loading
    });
  }

  baixarPdfAntigo() {
    const element = this.relatorioPdf.nativeElement;
    html2canvas(element, { scale: 2 }).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });
      const pageWidth = pdf.internal.pageSize.getWidth();
      //const pageHeight = pdf.internal.pageSize.getHeight();
      // Calculando dimensões para ajustar numa página A4
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pageWidth;
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
      // Ajustando a altura para não ultrapassar a página A4
      let position = 0;
      pdf.addImage(imgData, 'PNG', 0, position, pdfWidth, pdfHeight); // Use 'PNG' here
      pdf.save('relatorio.pdf');
    }).catch((error) => {
      console.error('Erro ao gerar PDF:', error);
    });
  }

  mostrarDetalhes(tributo: number) {
    const modalOptions: ModalOptions = {
      class: 'modal-lg',
      backdrop: true,
      ignoreBackdropClick: false,
      animated: true,
      initialState: {
        output: this.output,
        tributo: tributo
      }
    }
    this.bsModalService.show(ModalDetalhesComponent, modalOptions);
  }

  mostrarValidarXml(tributo: string) {
    const modalOptions: ModalOptions = {
      class: 'modal-xl',
      backdrop: true,
      ignoreBackdropClick: false,
      animated: true,
      initialState: {
        //detalhes: this.dados[tributo as keyof CalculadoraOutputModel],
        //tipoAliquota: this.tipoAliquota,
        //unidadeMedida: this.unidadeMedida,
        //output: dados
      }
    }
    this.bsModalService.show(ModalGeradorValidadorXmlComponent, modalOptions);
  }

  gerarXml() {
    this.mostrarValidarXml('validar');
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo) => {
        this.dispositivo = dispositivo;
      })
    );
  }

}
