import { Component, OnInit, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { BrModalSize, DefaultsService, GovBrFileModule, GovBrModalModule, GovBrTextAreaModule } from '@serpro/ngx-dsgovbr';
