@Component({
  selector: 'modal-gerador-validador-xml',
  templateUrl: './modal-gerador-validador-xml.component.html',
  styleUrl: './modal-gerador-validador-xml.component.scss',
  standalone: true,
  providers: [
    BsModalService
  ],
  imports: [
    CommonModule,
    GovBrModalModule,
    GovBrFileModule,
    ReactiveFormsModule,
    GovBrTextAreaModule,
    MonacoEditorModule,
    GeradorValidadorXmlComponent
  ]
})
export class ModalGeradorValidadorXmlComponent implements OnInit {

  editorOptions = {
    theme: 'vs-light',
    language: 'xml',
    automaticLayout: true,
    minimap: { enabled: false },
    overviewRulerLanes: 0,
    hideCursorInOverviewRuler: true,
    overviewRulerBorder: false,
    scrollBeyondLastLine: false,
    fontSize: 14,
    wordWrap: 'on',
    stickyScroll: { enabled: false }
  };

  xmlCode: string = '';

  resizeable = true;
  disabled = false;
  closeButton = true;
  size: BrModalSize = 'sm';

  xxx?: any;
  detalhes?: any;
  tipoAliquota: any;
  unidadeMedida: any;

  output?: any;

  form!: FormGroup;

  resposta: any = null;
  erro: any = null;

  placeholder!: string;

  tipoValues: Array<{ id: number; label: string; sigla: string }> = [];

  constructor(
    public bsModalService: BsModalService,
    public bsModalRef: BsModalRef,
    private defaultsService: DefaultsService,
    private readonly formBuilder: FormBuilder,
    private dadosCalculadoraService: DadosCalculadoraService,
    public xmlService: XmlService,
    private cdr: ChangeDetectorRef
  ) {

  }

  ngOnInit(): void {


    this.xmlService.obterDocumentosNaGeracao().subscribe({
      next: (data: any) => {
        this.xmlService.tiposDeDocumentoGeracao = data;
      },
      error: (error: any) => {
        console.error('Erro ao carregar documentos de geração:', error);
      }
    });


    this.output = this.dadosCalculadoraService.output;
    this.form = this.formBuilder.group({
      xmlControl: [this.xmlCode, []],
    });
    this.confirmar();
  }

  fechar() {
    this.bsModalRef.hide();
  }

  copiar() {
    const currentValue = this.form.get('xmlControl')?.value || '';
    if (currentValue) {
      navigator.clipboard.writeText(currentValue).then(() => {
      }).catch(err => {
      });
    }
  }

  colar() {
    navigator.clipboard.readText().then(text => {
      this.form.patchValue({ xmlControl: text });
      this.xmlCode = text; // Atualiza o código XML exibido
    }).catch(err => {
      console.error('Erro ao colar XML:', err);
    });
  }

  apagar() {
    this.form.patchValue({ xmlControl: '' });
    this.xmlCode = ''; // Limpa o código XML exibido
    this.resposta = null;
    this.erro = null;
  }

  // validar() {

  //   alert('A validação de XML foi movida para o componente Gerador/Validador de XML separado.');

  //   const xml: string = this.form.get('xmlControl')?.value;
  //   const tipo: string = 'nfe';
  //   const subtipo: string = 'grupo';

  //   if (xml == '' || xml == null || tipo == '' || tipo == null) {
  //     this.erro = { detail: 'XML e tipo são obrigatórios para validação.' };
  //     this.resposta = null;
  //     return;
  //   }

  //   this.xmlService.validarXml(xml, tipo, subtipo).subscribe({
  //     next: (response) => {
  //       this.resposta = response;
  //       this.erro = null;
  //     },
  //     error: (error) => {
  //       this.erro = error?.error || 'Erro desconhecido na validação do XML';
  //       this.resposta = null;
  //     }
  //   });
  // }

  organizarXml(xml: string): string {
    const xmlFormatado = this.xmlService.organizarXml(xml);
    return xmlFormatado;
  }

  organizar() {
    const currentValue = this.form.get('xmlControl')?.value || '';
    const formattedXml = this.organizarXml(currentValue);
    this.form.patchValue({ xmlControl: formattedXml });
    this.xmlCode = formattedXml;
  }

  confirmar() {
    //alert('A geração de XML foi movida para o componente Gerador/Validador de XML separado.');
    this.form.patchValue({ xmlControl: '' }); // Limpa o valor atual
    this.resposta = null;
    this.erro = null;

    this.xmlService.gerarXml(this.output, 'NFE').subscribe({
      next: (response) => {
        this.erro = null;
        const formattedXml = this.organizarXml(response);
        this.form.patchValue({ xmlControl: formattedXml });
        this.xmlCode = formattedXml;
        this.resposta = true;
        this.cdr.detectChanges();
        this.dadosCalculadoraService.xml = formattedXml; // Atualiza o XML no serviço
      },
      error: (error) => {
        this.erro = error?.error || 'Erro desconhecido na geração do XML';
        this.resposta = null;
        this.form.patchValue({ xmlControl: '' });
        this.xmlCode = '';
        this.cdr.detectChanges();
      }
    });
  }

  onSubmit(action: string) {
    if (action === 'validar') {
      //this.validar();
    } else if (action === 'restaurar') {
      this.restaurar();
    }
  }

  restaurar() {
    this.confirmar();
  }

}
