  private findInputElement(componentRef: any): HTMLInputElement | null {
    if (!componentRef) return null;
    // Tentando diferentes maneiras de encontrar o elemento input.
    // Isso ajuda a evitar problemas de compatibilidade com diferentes versões do Angular ou bibliotecas de terceiros.
    // É o caso do br-input.
    const methods = [
      () => componentRef.nativeElement?.querySelector('input'),
      () => componentRef.elementRef?.nativeElement?.querySelector('input'),
      () => componentRef.inputRef?.nativeElement,
      () => componentRef.element?.nativeElement?.querySelector('input'),
    ];

    for (const method of methods) {
      try {
        const element = method();
        if (element && element.tagName === 'INPUT') {
          return element;
        }
      } catch (error) {
        // continuando para o próximo método se houver um erro
      }
    }

    return null;
  }

