  calcular() {
    this.resetarValores();
    
    if (this.form.valid) {
      // The captcha verification will be handled by the interceptor
      // Just proceed with the calculation
      this.proceedWithCalculation();
    } else {
      this.mensagemService.mostrar('Erro', 'Erro', 'Formulário inválido.');
    }
  }

private proceedWithCalculation() {
    // tratamento dos campos
    let baseCalculo: any = this.form.get('baseCalculoControl')?.value;
    /////////////////////////////////
    let body = this.obterBody(baseCalculo);
    this.dadosCalculadoraService.input = body;
    if (environment.profile == 'local') {
      this.salvarArquivo(body);
    }
    
    this.calcularService.calcularTributos(body).subscribe({
      next: (data) => {
        this.dadosCalculadoraService.input = body;
        this.dadosCalculadoraService.output = data;

        // resetar o captcha após sucesso - os tokens são de uso único
        this.captchaService.clear();

        // para retirar a versão de importação
        this.dadosCalculadoraService.versaoImportacao = null;
        
        this.mensagemService.mostrar('Sucesso', 'Sucesso', 'Cálculo realizado com sucesso.');
        if (environment.profile == 'local') {
          this.salvarArquivo(data);
        }
      },
      error: (error) => {
        // resetar o captcha após erros - o usuário precisa de um novo token para tentar novamente
        this.captchaService.clear();
        console.error('Erro no processamento:', error);
        // os erros são gerenciados pelo interceptor de captcha
      }
    })
  }

