  // Esse é o método principal => Existe também um método de fallback.
  private focusOnInput(inputRef: any): void {
    if (!inputRef) return;
    setTimeout(() => {
      try {
        // tentando encontrar o elemento input no componente
        const inputElement = this.findInputElement(inputRef);
        if (inputElement && typeof inputElement.focus === 'function') {
          inputElement.focus();
        } else {
        }
      } catch (error) {
      }
    }, 100);
  }

  // Esse é o método de fallback => Ele tenta encontrar o elemento no DOM.
  private focusOnFormControl(controlName: string): void {
    setTimeout(() => {
      try {
        // tentativa 1
        // tentando encontrar o elemento form control pelo nome
        const formControlElement = document.querySelector(`[formcontrolname="${controlName}"]`);
        if (formControlElement) {
          const inputElement = formControlElement.querySelector('input');
          if (inputElement && typeof inputElement.focus === 'function') {
            inputElement.focus();
            return;
          }
        }
        // tentativa 2
        // tentando encontrar o elemento input pelo ID
        const inputById = document.querySelector(`#${controlName}`) as HTMLInputElement;
        if (inputById && typeof inputById.focus === 'function') {
          inputById.focus();
          return;
        }
      } catch (error) {
      }
    }, 100);
  }

  private isInputFocused(inputType: 'ncm' | 'nbs'): boolean {
    const activeElement = document.activeElement;
    if (!activeElement) return false;
    // checando se o elemento ativo é um input
    if (activeElement.tagName !== 'INPUT') return false;
    // checando se o input está dentro de um form control com o nome esperado
    const formControlContainer = activeElement.closest('[formcontrolname]');
    if (!formControlContainer) return false;
    const formControlName = formControlContainer.getAttribute('formcontrolname');
    return formControlName === `${inputType}Control`;
  }

