  private pauseNcmNbsSubscriptions() {
    this.ncmSubscription?.unsubscribe();
    this.nbsSubscription?.unsubscribe();
  }

  private resumeNcmNbsSubscriptions() {
    // Recreate NCM subscription
    this.ncmSubscription = this.form.get('ncmControl')?.valueChanges.pipe(
      debounceTime(SimuladorCalculoComponent.DEBOUNCE_TIME_MS),
      distinctUntilChanged()
    ).subscribe(value => {
      this.ncmControlChange(value);
    });
    if (this.ncmSubscription) {
      this.subscriptions.add(this.ncmSubscription);
    }

    // Recreate NBS subscription
    this.nbsSubscription = this.form.get('nbsControl')?.valueChanges.pipe(
      debounceTime(SimuladorCalculoComponent.DEBOUNCE_TIME_MS),
      distinctUntilChanged()
    ).subscribe(value => {
      this.nbsControlChange(value);
    });
    if (this.nbsSubscription) {
      this.subscriptions.add(this.nbsSubscription);
    }
  }

