  importarDados() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (event: any) => {
      this.dadosCalculadoraService.limparDados();
      const file = event.target.files[0];
      if (!file) {
        return;
      }
      const reader = new FileReader();
      reader.onload = (e: any) => {
        try {
          const base64Data = e.target.result;
          this.dadosCalculadoraService.importarDados(base64Data);
          this.restaurarEstadoCompleto();
        } catch (error) {
          this.mensagemService.mostrar('Erro', 'Erro', 'Arquivo inválido');
          console.error('Erro ao importar os dados:', error);
        }
      };
      reader.readAsText(file);
    };
    input.click();
  }

