import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { BrModalSize, GovBrModalModule } from '@serpro/ngx-dsgovbr';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';

@Component({
  selector: 'modal-detalhes',
  templateUrl: './modal-detalhes.component.html',
  styleUrl: './modal-detalhes.component.scss',
  standalone: true,
  providers: [BsModalService], // aqui é necessário fornecer o serviço - por quê?
  imports: [
    CommonModule, GovBrModalModule
  ]
})
export class ModalDetalhesComponent {

  resizeable = true;
  disabled = false;
  closeButton = true;
  size: BrModalSize = 'sm';

  xxx?: any;
  detalhes?: any;
  tipoAliquota: any;
  unidadeMedida: any;

  output?: any;

  tributo?: number;
  // 0 - cbs
  // 1 - ibs estadual
  // 2 - ibs municipal
  // 3 - is

  constructor(
    public bsModalService: BsModalService,
    public bsModalRef: BsModalRef,
  ) { }

  fechar() {
    this.bsModalRef.hide();
  }

}
